// ─── SEEDED RANDOM FUNCTION ──────────────────────────────────────────────────
function seededRandom(seed) {
  const x = Math.sin(seed + 1) * 10000;
  return x - Math.floor(x);
}

// ─── GENERATE JOB DATA ──────────────────────────────────────────────────────
function getJobData(id) {
  const seed = id * 7919;
  const r = (offset = 0) => seededRandom(seed + offset);

  const isRemote = id <= TOTAL_JOBS / 2;

  const companyIndex = Math.floor((id - 1) / Math.ceil(TOTAL_JOBS / companies.length)) % companies.length;

  const titleIndex   = Math.floor(r(1) * jobTitles.length);
  const locationIndex= Math.floor(r(3) * singaporeLocations.length);
  const salaryIndex  = Math.floor(r(4) * salaryRanges.length);
  const jobTypeIndex = Math.floor(r(5) * jobTypes.length);
  const expIndex     = Math.floor(r(6) * experienceLevels.length);
  const industryIndex= Math.floor(r(7) * industries.length);
  const descIndex    = Math.floor(r(8) * jobDescriptions.length);

  const title    = jobTitles[titleIndex];
  const company  = companies[companyIndex];
  const location = isRemote ? "Remote — Singapore" : singaporeLocations[locationIndex];
  const salary   = salaryRanges[salaryIndex];
  const jobType  = jobTypes[jobTypeIndex];
  const exp      = experienceLevels[expIndex];
  const industry = industries[industryIndex];
  const description = jobDescriptions[descIndex](title, company, isRemote, singaporeLocations[locationIndex]);

  const daysAgo = Math.floor(r(9) * 60);
  const postedDate = new Date();
  postedDate.setDate(postedDate.getDate() - daysAgo);
  const validThrough = new Date(postedDate);
  validThrough.setDate(validThrough.getDate() + 90);

  // Generate slug from title + company + id
  const slug = `${title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${company.toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${id}`;

  return {
    id,
    title,
    company,
    location,
    salary: salary.display,
    salaryMin: salary.min,
    salaryMax: salary.max,
    jobType,
    jobTypeDisplay: jobTypeDisplay[jobType],
    experience: exp.display,
    experienceSchema: exp.schema,
    industry,
    isRemote,
    description,
    postedDate: postedDate.toISOString().split('T')[0],
    validThrough: validThrough.toISOString().split('T')[0],
    slug
  };
}

// ─── GET JOB SCHEMA ──────────────────────────────────────────────────────────
function getJobSchema(job) {
  const schema = {
    "@context": "https://schema.org/",
    "@type": "JobPosting",
    "title": job.title,
    "description": job.description,
    "identifier": {
      "@type": "PropertyValue",
      "name": job.company,
      "value": `JOB-SG-${String(job.id).padStart(6, '0')}`
    },
    "datePosted": job.postedDate,
    "validThrough": `${job.validThrough}T00:00:00Z`,
    "employmentType": job.jobType,
    "hiringOrganization": {
      "@type": "Organization",
      "name": job.company,
      "sameAs": `https://www.google.com/search?q=${encodeURIComponent(job.company)}`
    },
    "jobLocation": {
      "@type": "Place",
      "address": {
        "@type": "PostalAddress",
        "addressLocality": job.isRemote ? "Singapore" : job.location.split(',')[0],
        "addressCountry": "SG"
      }
    },
    "applicantLocationRequirements": {
      "@type": "Country",
      "name": "Singapore"
    },
    "baseSalary": {
      "@type": "MonetaryAmount",
      "currency": "SGD",
      "value": {
        "@type": "QuantitativeValue",
        "minValue": job.salaryMin,
        "maxValue": job.salaryMax,
        "unitText": "MONTH"
      }
    },
    "experienceRequirements": {
      "@type": "OccupationalExperienceRequirements",
      "monthsOfExperience": job.experienceSchema === "no requirements" ? 0
        : parseInt(job.experienceSchema) * 12
    },
    "industry": job.industry,
    "url": `/jobs/${job.id}`,
    "directApply": true
  };

  if (job.isRemote) {
    schema.jobLocationType = "TELECOMMUTE";
  }

  return schema;
}

// ─── KEYWORDS PARSER ─────────────────────────────────────────────────────────
// This function processes your keyword file to generate additional job titles
function parseKeywordFile(keywordText) {
  const keywords = keywordText.split(',').map(k => k.trim());
  return keywords;
}

// Add keywords to job titles for more variety
function addKeywordsToJobTitles(keywordText) {
  const keywords = parseKeywordFile(keywordText);
  
  // Extract relevant job-related keywords from the list
  const jobKeywords = keywords.filter(k => {
    const lower = k.toLowerCase();
    return lower.includes('job') || 
           lower.includes('work') || 
           lower.includes('remote') || 
           lower.includes('hiring') || 
           lower.includes('career') ||
           lower.includes('employment');
  });
  
  // Add some as additional job titles (limit to 500 to avoid duplicates)
  const maxAdd = Math.min(500, jobKeywords.length);
  for (let i = 0; i < maxAdd; i++) {
    const keyword = jobKeywords[i];
    // Clean up keyword to use as job title
    const cleanKeyword = keyword
      .replace(/^"|"$/g, '')
      .replace(/\b(job|work|hiring|career|remote|employment)\b/gi, '')
      .trim();
    
    if (cleanKeyword && cleanKeyword.length > 3 && !jobTitles.includes(cleanKeyword)) {
      jobTitles.push(cleanKeyword);
    }
  }
  
  return jobTitles;
}

// ─── EXPORTS ──────────────────────────────────────────────────────────────────
module.exports = { 
  getJobData, 
  getJobSchema, 
  TOTAL_JOBS, 
  jobTitles, 
  companies, 
  singaporeLocations, 
  industries,
  parseKeywordFile,
  addKeywordsToJobTitles
};
